{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Reach & Gather</title>
  <meta name="description" content="Reach {{PRACTITIONER_NAME}} for aromatherapy events, consultations and gentle guidance in {{CITY}}, {{STATE}}. Safety-first, scent-forward." />
  <style>
    :root{
      --bg1: #f6f7f9;
      --accent: #7aa27a;
      --muted: #6b6b6b;
      --card: #ffffff;
      --glass: rgba(255,255,255,0.6);
      --shadow: 0 6px 22px rgba(9,10,12,0.06);
      --radius: 14px;
      --max: 980px;
      --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, "Roboto Mono", "Segoe UI Mono", "Helvetica Neue", monospace;
    }
    *{box-sizing:border-box}
    html,body{height:100%}
    body{
      margin:0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;
      color:#122218;
      background: linear-gradient(180deg, rgba(122,162,122,0.06) 0%, rgba(246,247,249,1) 40%);
      -webkit-font-smoothing:antialiased;
      -moz-osx-font-smoothing:grayscale;
      display:flex;justify-content:center;padding:48px 20px;
    }
    .site{
      width:100%;max-width:var(--max);position:relative;
      background: linear-gradient(180deg, rgba(255,255,255,0.7), rgba(255,255,255,0.86));
      border-radius:20px;padding:36px;box-shadow:var(--shadow);
      overflow:hidden;
    }
    /* decorative svg block */
    .pattern{
      position:absolute;right:-120px;top:-60px;opacity:0.24;transform:rotate(12deg);pointer-events:none;width:520px;height:520px;
      filter: drop-shadow(0 10px 30px rgba(122,162,122,0.07));
    }
    header{display:flex;align-items:center;justify-content:space-between;gap:18px}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:58px;height:58px;border-radius:12px;background:linear-gradient(135deg,#89b889,#5d8f5d);display:flex;align-items:center;justify-content:center;color:white;font-weight:700;font-family:var(--mono);letter-spacing:0.6px}
    nav{display:flex;gap:12px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:10px;font-size:14px}
    nav a[href$="contact.html"]{background:rgba(122,162,122,0.08);color:var(--accent)}
    main{display:grid;grid-template-columns:1fr 420px;gap:28px;padding-top:20px}
    @media (max-width:920px){main{grid-template-columns:1fr;}
      .pattern{display:none}}

    /* left column */
    .hero{
      background:linear-gradient(180deg, rgba(255,255,255,0.6), rgba(250,250,250,0.8));
      padding:28px;border-radius:14px;border:1px solid rgba(14,18,12,0.03);
    }
    .hero h1{margin:0 0 8px 0;font-size:22px;letter-spacing:0.2px}
    .hero p{margin:0 0 14px 0;color:var(--muted);line-height:1.45}
    .info-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:18px}
    .pill{background:var(--card);padding:12px;border-radius:12px;border:1px solid rgba(9,10,12,0.03);}
    .pill strong{display:block;color:#223322}
    .safety{margin-top:16px;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#fbfff9);border-left:4px solid var(--accent);color:#2b4b2b}

    /* right column - contact form */
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.9), var(--glass));padding:22px;border-radius:14px;border:1px solid rgba(9,10,12,0.04)}
    form{display:grid;gap:10px}
    label{font-size:13px;color:#334433}
    input[type=text],input[type=email],input[type=tel],select,textarea{
      width:100%;padding:10px;border-radius:10px;border:1px solid rgba(9,10,12,0.06);font-size:14px;background:transparent;resize:vertical}
    textarea{min-height:120px}
    .row{display:flex;gap:10px}
    .small{flex:1}
    button{background:var(--accent);color:white;padding:12px 14px;border-radius:12px;border:0;font-weight:600;cursor:pointer}
    .muted{font-size:13px;color:var(--muted)}
    .cta-row{display:flex;gap:8px;align-items:center;justify-content:space-between;margin-top:10px}
    .phone{font-size:14px;color:#234423}

    /* success overlay */
    .overlay{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(18,34,24,0.28);backdrop-filter:blur(4px)}
    .note{background:linear-gradient(180deg,#ffffff,#f6fff7);padding:26px;border-radius:12px;box-shadow:0 10px 40px rgba(10,30,20,0.12);max-width:520px;text-align:center}
    .note h3{margin:0 0 6px 0}
    .note p{margin:0 0 14px 0;color:var(--muted)}
    .note button{background:transparent;border:1px solid rgba(9,10,12,0.06);padding:10px 12px;border-radius:10px}

    footer{margin-top:22px;padding-top:18px;border-top:1px dashed rgba(9,10,12,0.04);display:flex;justify-content:space-between;align-items:center}
    .micro{font-size:13px;color:var(--muted)}
  </style>
</head>
<body>
  <div class="site" role="banner">
    <!-- decorative svg pattern (unique, lightweight) -->
    <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">
      <defs>
        <linearGradient id="g1" x1="0" x2="1">
          <stop offset="0" stop-color="#b7e0b7" stop-opacity="0.85"/>
          <stop offset="1" stop-color="#7aa27a" stop-opacity="0.65"/>
        </linearGradient>
        <pattern id="patt" patternUnits="userSpaceOnUse" width="28" height="28" patternTransform="rotate(12)">
          <rect width="28" height="28" fill="rgba(255,255,255,0.02)"/>
          <circle cx="4" cy="4" r="2.2" fill="#ffffff" opacity="0.06" />
        </pattern>
      </defs>
      <rect width="200" height="200" fill="url(#g1)" rx="28"/>
      <rect width="200" height="200" fill="url(#patt)" rx="28"/>
      <g fill="rgba(255,255,255,0.12)">
        <path d="M40 160c20-28 60-32 95-10" stroke="none"/>
      </g>
    </svg>

    <header>
      <div class="brand">
        <div class="logo" aria-hidden="true">Aro</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:13px;color:var(--muted);">Aromatherapy events & gentle consultations</div>
        </div>
      </div>
      <nav aria-label="Primary">
        <a href="index.html">Gather</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Story</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <main role="main">
      <section class="hero" aria-labelledby="reach-title">
        <h1 id="reach-title">A quiet place to reach {{PRACTITIONER_NAME}}</h1>
        <p>Leave a note about your interest — group classes, private sessions, or the upcoming series of scented gatherings. We respond thoughtfully within 48 hours. Aromatherapy is supportive and non-medical; safety and clarity first.</p>

        <div class="info-grid" aria-hidden="false">
          <div class="pill">
            <strong>Events Series</strong>
            <span class="muted">Small group scent rituals, seasonal themes — an ongoing series of gentle learning</span>
          </div>
          <div class="pill">
            <strong>Phone</strong>
            <span class="muted">{{PHONE}} — voice & text</span>
          </div>
          <div class="pill">
            <strong>Email</strong>
            <span class="muted">{{EMAIL}}</span>
          </div>
          <div class="pill">
            <strong>Location</strong>
            <span class="muted">Serving {{CITY}}, {{STATE}} — studio & pop-ups</span>
          </div>
        </div>

        <div class="safety" role="note">
          <strong>Safety-first</strong>
          <div class="muted">I provide guidance on safe use, dilution and patch testing. I do not diagnose or treat medical conditions. Please indicate pregnancy, nursing, or pet concerns in your message so I can advise attention to safety.</div>
        </div>
      </section>

      <aside class="card" aria-labelledby="contact-form-title">
        <h2 id="contact-form-title" style="margin-top:0;margin-bottom:6px;font-size:18px">Send a short note</h2>
        <p class="muted" style="margin-top:0;margin-bottom:12px">Tell me about the best way to reach you and which offering sparks curiosity.</p>

        <form id="contactForm" autocomplete="on">
          <div class="row">
            <div class="small">
              <label for="name">Name</label>
              <input id="name" name="name" type="text" placeholder="Your name" required>
            </div>
            <div class="small">
              <label for="phone">Phone</label>
              <input id="phone" name="phone" type="tel" placeholder="Optional">
            </div>
          </div>

          <label for="email">Email</label>
          <input id="email" name="email" type="email" placeholder="you@example.com" required>

          <label for="interest">I am interested in</label>
          <select id="interest" name="interest">
            <option>Group event (series)</option>
            <option>Private consultation</option>
            <option>Wholesale / partner</option>
            <option>Blends & boutique</option>
            <option>Other</option>
          </select>

          <label for="message">Message</label>
          <textarea id="message" name="message" placeholder="A short note, days/times you prefer, questions about safety/dilution, or mention {{FAVORITE_BLEND}}..." ></textarea>

          <div style="display:flex;gap:10px;align-items:center;justify-content:space-between;margin-top:6px">
            <label style="display:flex;gap:8px;align-items:center;">
              <input type="checkbox" id="consent" required>
              <span class="muted">I understand aromatherapy is supportive and not medical care.</span>
            </label>
            <div class="phone">Prefer to call? <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a></div>
          </div>

          <div class="cta-row">
            <div style="display:flex;gap:8px">
              <button type="submit">{{PRIMARY_CTA_LABEL}}</button>
              <button type="button" onclick="window.location.href='book.html'" style="background:transparent;border:1px solid rgba(9,10,12,0.06);">Reserve</button>
            </div>
            <div class="muted">Response expected within 48 hours</div>
          </div>
        </form>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">
          <strong>Quick notes</strong>
          <ul style="margin:8px 0 0 18px;padding:0;color:var(--muted)">
            <li>Include pregnancy, nursing, pet, or medication notes so I can flag safety considerations.</li>
            <li>For scent-sensitive guests, request low-intensity options for events.</li>
          </ul>
        </div>

      </aside>
    </main>

    <footer>
      <div class="micro">© {{BUSINESS_NAME}} — {{PRACTITIONER_NAME}} • Serving {{CITY}}, {{STATE}}</div>
      <div class="micro">Need immediate help? Call <a href="tel:{{PHONE}}" style="color:var(--accent);text-decoration:none">{{PHONE}}</a></div>
    </footer>
  </div>

  <div class="overlay" id="overlay" role="dialog" aria-modal="true">
    <div class="note">
      <h3>Thank you — message sent</h3>
      <p>We received your note. We'll reply shortly with available times and next steps for safe, grounded aromatherapy exploration.</p>
      <button onclick="closeOverlay()">Close</button>
    </div>
  </div>

  <script>
    (function(){
      const form = document.getElementById('contactForm');
      const overlay = document.getElementById('overlay');
      form.addEventListener('submit', function(e){
        e.preventDefault();
        // Simple client-side validation already handled by required attributes
        // Simulate a send, then show an overlay confirmation.
        overlay.style.display = 'flex';
        // clear form after a short pause
        setTimeout(()=>{form.reset();},450);
      });
      window.closeOverlay = function(){ overlay.style.display = 'none'; }
      // Accessibility: close overlay on Escape
      window.addEventListener('keydown', function(ev){ if(ev.key === 'Escape'){ overlay.style.display='none'; } });
    })();
  </script>
</body>
</html>"} 
